// Pick the single most urgent overdue follow-up. One nudge, one action.
// State lives in the table itself: next_step_due IS the follow-up date, and
// pushing it forward is the snooze. No extra columns required.
const STAGE_WEIGHT = {
  'Prospect': 0, 'Meeting Booked': 1, 'Qualified': 2,
  'Proposal Sent': 3, 'Decision Pending': 4,
};

const laToday = () => {
  const s = new Date().toLocaleString('en-US', { timeZone: 'America/Los_Angeles' });
  const d = new Date(s);
  return new Date(d.getFullYear(), d.getMonth(), d.getDate());
};
const dayOf = (v) => {
  if (!v) return null;
  const d = new Date(v);
  if (isNaN(d)) return null;
  return new Date(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate());
};
const daysBetween = (a, b) => Math.round((a - b) / 86400000);

const today = laToday();
const rows = $input.all().map(i => i.json).filter(r => r && r.name);
const live = rows.filter(r => r.stage && !String(r.stage).startsWith('Closed'));

const due = [];
for (const r of live) {
  const dueDay = dayOf(r.next_step_due);
  if (!dueDay) continue;
  const overdue = daysBetween(today, dueDay);
  if (overdue < 0) continue;                      // not due yet
  const touchDay = dayOf(r.last_touch);
  const sinceTouch = touchDay ? daysBetween(today, touchDay) : null;
  if (sinceTouch === 0) continue;                 // already actioned today
  due.push({ r, overdue, sinceTouch, weight: STAGE_WEIGHT[r.stage] ?? 0 });
}

if (due.length === 0) {
  return [{ json: { fire: false } }];
}

// Money on the table wins. A Proposal Sent seven days overdue beats a Prospect
// sixty days overdue: the first has a live counterparty and a clock, the second
// is neglect that will otherwise hijack this nudge every day forever.
due.sort((a, b) => (b.weight - a.weight) || (b.overdue - a.overdue));
const top = due[0];
const r = top.r;

let head;
if (top.overdue >= 14)     head = '\u{1F6A8} Follow-up badly overdue';
else if (top.overdue >= 7) head = '\u{1F534} Follow-up a week overdue';
else if (top.overdue >= 3) head = '\u{1F7E0} Follow-up overdue';
else                       head = '\u{1F514} Follow-up due';

const who = r.company ? `${r.name} (${r.company})` : r.name;
const overdueTxt = top.overdue === 0 ? 'due today'
  : `${top.overdue} day${top.overdue === 1 ? '' : 's'} overdue`;
const touchTxt = top.sinceTouch === null ? 'never touched'
  : `last touch ${top.sinceTouch}d ago`;

let step = String(r.next_step || '').trim();
if (!step) step = '(no documented next step - that is the problem)';
if (step.length > 220) step = step.slice(0, 217) + '...';

const rest = due.slice(1);
let tail = '';
if (rest.length) {
  const oldest = Math.max(...rest.map(d => d.overdue));
  tail = `\n\n${rest.length} other row${rest.length === 1 ? '' : 's'} overdue, ` +
         `oldest ${oldest}d. Clear or close them.`;
}

const text =
  `${head}\n\n` +
  `${who}\n` +
  `${r.stage} · ${overdueTxt} · ${touchTxt}\n\n` +
  `Next step:\n${step}\n\n` +
  `→ Do this one thing today, then update the row.` +
  `${tail}`;

return [{ json: { fire: true, text, id: r.id, name: r.name, overdue: top.overdue } }];
